     1	// The browser side: draws the board, sends each move to the server and
     2	// shows what it answers. The rules live on the server (tictactoe/game.py).
     3	"use strict";
     4	
     5	const boardEl = document.getElementById("board");
     6	const statusEl = document.getElementById("status");
     7	const modeEl = document.getElementById("mode");
     8	const levelEl = document.getElementById("level");
     9	const levelLabel = document.getElementById("level-label");
    10	const score = { X: 0, O: 0, draw: 0 };
    11	
    12	let state = null; // the server's last answer
    13	let busy = false; // a move is on its way to the server
    14	let focused = 0; // the cell that holds the board's single tab stop
    15	
    16	const cells = Array.from({ length: 9 }, (_, i) => {
    17	  const cell = document.createElement("button");
    18	  cell.type = "button";
    19	  cell.className = "cell";
    20	  cell.addEventListener("click", () => move(i));
    21	  cell.addEventListener("keydown", (event) => onKey(event, i));
    22	  cell.addEventListener("focus", () => { focused = i; });
    23	  boardEl.appendChild(cell);
    24	  return cell;
    25	});
    26	
    27	function newGame() {
    28	  state = { board: Array(9).fill(""), status: "playing", winner: null, line: null, turn: "X" };
    29	  levelLabel.hidden = modeEl.value !== "computer";
    30	  render();
    31	}
    32	
    33	async function move(cell) {
    34	  if (busy || state.status !== "playing" || state.board[cell]) return;
    35	  busy = true;
    36	  try {
    37	    const response = await fetch("/api/move", {
    38	      method: "POST",
    39	      headers: { "Content-Type": "application/json" },
    40	      body: JSON.stringify({ board: state.board, cell, mode: modeEl.value, level: levelEl.value }),
    41	    });
    42	    const answer = await response.json();
    43	    if (!response.ok) throw new Error(answer.error || response.statusText);
    44	    state = answer;
    45	    if (state.status === "won") score[state.winner] += 1;
    46	    if (state.status === "draw") score.draw += 1;
    47	  } catch (error) {
    48	    statusEl.textContent = `Something went wrong: ${error.message}`;
    49	    return;
    50	  } finally {
    51	    busy = false;
    52	  }
    53	  render();
    54	}
    55	
    56	function render() {
    57	  const winning = new Set(state.line || []);
    58	  cells.forEach((cell, i) => {
    59	    const mark = state.board[i];
    60	    cell.textContent = mark;
    61	    cell.className = `cell ${mark.toLowerCase()} ${winning.has(i) ? "win" : ""}`;
    62	    // aria-disabled, not disabled: a disabled button cannot keep the focus
    63	    cell.setAttribute("aria-disabled", String(state.status !== "playing" || Boolean(mark)));
    64	    cell.tabIndex = i === focused ? 0 : -1;
    65	    const row = Math.floor(i / 3) + 1;
    66	    const col = (i % 3) + 1;
    67	    const what = mark || "empty";
    68	    cell.setAttribute("aria-label", `Row ${row}, column ${col}, ${what}${winning.has(i) ? ", winning" : ""}`);
    69	  });
    70	  statusEl.textContent = describe();
    71	  document.getElementById("score-x").textContent = score.X;
    72	  document.getElementById("score-o").textContent = score.O;
    73	  document.getElementById("score-draw").textContent = score.draw;
    74	}
    75	
    76	function describe() {
    77	  const vsComputer = modeEl.value === "computer";
    78	  if (state.status === "won") {
    79	    if (!vsComputer) return `${state.winner} wins!`;
    80	    return state.winner === "X" ? "You win!" : "The computer wins.";
    81	  }
    82	  if (state.status === "draw") return "It's a draw.";
    83	  if (vsComputer) return "Your turn (X)";
    84	  return `${state.turn} to play`;
    85	}
    86	
    87	const STEPS = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -3, ArrowDown: 3 };
    88	
    89	function onKey(event, i) {
    90	  let next = null;
    91	  if (event.key in STEPS) {
    92	    const step = STEPS[event.key];
    93	    const target = i + step;
    94	    const sameRow = Math.floor(target / 3) === Math.floor(i / 3);
    95	    if (target >= 0 && target < 9 && (Math.abs(step) === 3 || sameRow)) next = target;
    96	  } else if (event.key === "Home") {
    97	    next = 0;
    98	  } else if (event.key === "End") {
    99	    next = 8;
   100	  } else {
   101	    return; // Enter and Space click the button by themselves
   102	  }
   103	  event.preventDefault();
   104	  if (next !== null) {
   105	    focused = next;
   106	    render();
   107	    cells[next].focus();
   108	  }
   109	}
   110	
   111	document.getElementById("new-game").addEventListener("click", newGame);
   112	modeEl.addEventListener("change", newGame);
   113	levelEl.addEventListener("change", newGame);
   114	newGame();
